      // ----------------------------------------------------------------------
      // Helpers
      // ----------------------------------------------------------------------

      //! Write a command packet's descriptor and opcode
      //!
      //! The opcode is the remote's absolute one, which is what its command dispatcher
      //! matches on.
      Fw::SerializeStatus beginCommandPacket(
          Fw::ComBuffer& packet, //!< The packet to write into
          ::RefProxy::RefProxy_FwOpcodeType opcode //!< The remote's opcode
      ) const;

      //! Send a finished command packet and respond to the caller
      //!
      //! An OK response means the packet was sent, not that the remote ran the command:
      //! the remote's own dispatcher reports that as one of its events, which this
      //! component relays separately.
      void sendCommandPacket(
          FwOpcodeType opCode, //!< The local opcode
          U32 cmdSeq, //!< The command sequence number
          Fw::ComBuffer& packet, //!< The packet to send
          Fw::SerializeStatus status //!< How serialization turned out
      );

      //! Count one decode attempt, successful or not
      void recordDecodeResult(
          U32 descriptor, //!< The packet descriptor
          U32 identifier, //!< The event, channel or packet id
          Fw::SerializeStatus status //!< How the decode turned out
      );

      //! Report a packet that did not deserialize
      void recordDecodeError(
          U32 descriptor, //!< The packet descriptor
          U32 identifier, //!< The id, or zero if the decode failed before it
          Fw::SerializeStatus status //!< The failing status
      );

      //! Report a well-formed packet this proxy does not mirror
      void recordPacketIgnored(
          U32 descriptor, //!< The packet descriptor
          U32 identifier //!< The id, or zero if none was read
      );

    private:

      // ----------------------------------------------------------------------
      // Member variables
      // ----------------------------------------------------------------------

      //! Packets decoded into an event or a channel
      U32 m_packetsDecoded;

      //! Packets that did not deserialize
      U32 m_decodeErrors;

      //! Packets this proxy does not mirror
      U32 m_packetsIgnored;

